entries[386670] = { ["name"] = "EZ-Thro Grease Grenade", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Decay , Handful of Serevite Bolts (4), Everburning Blasting Powder (6), Assorted Safety Fuses\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nDiscovery:\nWhen crafting Grease Grenade\nRequires:\nSpecialization: Explosives - EZ-Thro\n\nEZ-Thro Grease Grenade\n\nUse: Launch a concealed grenade toward the target location, dealing 837 Nature damage and coating the ground in a sticky substance for 4 sec that slows enemy units within by 75%. (5 Min Cooldown)\n58\n\"So EZ that even non-Engineers can use it!\"" }
